#!/bin/sh
cd "${0%/*}" || exit # Run from this directory
. ${WM_PROJECT_DIR:?}/bin/tools/RunFunctions # Tutorial run functions
#------------------------------------------------------------------------------
mkdir -p constant/triSurface
# copy DTC hull surface from resources folder
cp -f \
"$FOAM_TUTORIALS"/resources/geometry/DTC-scaled.stl.gz \
constant/triSurface/
runApplication surfaceFeatureExtract
runApplication blockMesh
for i in 1 2 3 4 5 6
do
runApplication -s "$i" \
topoSet -dict system/topoSetDict.${i}
runApplication -s "$i" \
refineMesh -dict system/refineMeshDict -overwrite
done
runApplication snappyHexMesh -overwrite
restore0Dir
runApplication setFields
runApplication decomposePar
runParallel renumberMesh -overwrite
runParallel $(getApplication)
runApplication reconstructPar
#------------------------------------------------------------------------------
cd 切换当前工作目录。
mkdir 创建一个或多个目录。
cp 复制文件或目录。
surfaceFeatureExtract 从表面提取特征线，供 snappyHexMesh 控制棱边细化。
blockMesh 读取 blockMeshDict，生成由六面体块组成的网格。
topoSet 按几何、网格属性和集合关系创建或修改 sets/zones。
refineMesh 沿指定方向细化全域或选定单元。结果覆盖当前网格。
snappyHexMesh 细化背景网格，贴合几何表面，并按设置生成边界层。结果覆盖当前网格。
restore0Dir 将 0.orig 恢复为求解所用的 0 目录。
setFields 按几何选区或拓扑集合给已有场设置初值。
decomposePar 把网格和场划分到多个处理器子域。
renumberMesh 重排单元与面编号以减小矩阵带宽，并同步重排场。结果覆盖当前网格。通过并行包装函数执行，进程数与分区设置配套。
从 system/controlDict 的 application 读取求解器名称，运行后将日志保存在算例目录。
reconstructPar 把并行结果的字段重构到完整案例。
