{
version 2.0;
format ascii;
class dictionary;
object transportProperties;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //
phases (sludge water);
sludge
{
transportModel BinghamPlastic;
"(plastic|BinghamPlastic)Coeffs"
{
coeff 0.00023143;
exponent 179.26;
BinghamCoeff 0.0005966;
BinghamExponent 1050.8;
BinghamOffset 0;
muMax 10;
}
rho 1996;
}
water
{
transportModel Newtonian;
nu 1.7871e-06;
rho 996;
}
relativeVelocityModel simple;
"(simple|general)Coeffs"
{
V0 (0 -0.002198 0);
a 285.84;
a1 0.1;
residualAlpha 0;
}
// ************************************************************************* //
constant/transportProperties 中各项设置的作用如下。
phases 设为 (sludge water)：列出参与计算的相名称；字段后缀与物性子字典按这些名称对应。
sludge/transportModel 设为 BinghamPlastic：选择运动黏度关系。
sludge/rho 设为 1996：密度，单位 kg/m³。
water/transportModel 设为 Newtonian：选择运动黏度关系。
water/nu 设为 1.7871e-06：运动黏度，单位 m²/s。
water/rho 设为 996：密度，单位 kg/m³。
relativeVelocityModel 设为 simple：选择相对速度模型。
"(simple|general)Coeffs"/V0 设为 (0 -0.002198 0)：模型中的特征漂移速度向量。
"(simple|general)Coeffs"/a 设为 285.84：体积分数对漂移速度影响的经验系数。
"(simple|general)Coeffs"/a1 设为 0.1：体积分数对漂移速度影响的经验系数。
"(simple|general)Coeffs"/residualAlpha 设为 0：小体积分数处理所用参数。
