#!/bin/sh
cd "${0%/*}" || exit # Run from this directory
. ${WM_PROJECT_DIR:?}/bin/tools/RunFunctions # Tutorial run functions
#------------------------------------------------------------------------------
runApplication blockMesh
runApplication topoSet
# Restore initial fields
restore0Dir
runApplication splitMeshRegions -cellZones -overwrite
# Remove fluid fields from solid regions (important for post-processing)
fields="rho nut alphat epsilon k U p_rgh qr G IDefault"
for region in $(foamListRegions solid)
do
remove0DirFields -region "$region" -- $fields
done
for region in $(foamListRegions)
do
runApplication -s "$region" changeDictionary -region "$region"
done
#------------------------------------------------------------------------------
cd 切换当前工作目录。
blockMesh 读取 blockMeshDict，生成由六面体块组成的网格。
topoSet 按几何、网格属性和集合关系创建或修改 sets/zones。
restore0Dir 将 0.orig 恢复为求解所用的 0 目录。
splitMeshRegions 按网格连通性或 cellZone 将网格拆分成多个区域。结果覆盖当前网格。
foamListRegions 列出算例中的体网格区域或有限面积区域。
remove0DirFields 删除 0 目录中指定名称的场文件。处理区域由 "$region" 指定。
changeDictionary 按替换字典批量修改场文件或网格字典条目。处理区域由 "$region" 指定。
