#!/bin/sh
cd "${0%/*}" || exit # Run from this directory
. ${WM_PROJECT_DIR:?}/bin/tools/RunFunctions # Tutorial run functions
#------------------------------------------------------------------------------
restore0Dir
runApplication blockMesh
runApplication $(getApplication)
if notTest "$@"
then
cp -f system/controlDict system/controlDict.orig
foamDictionary system/controlDict -entry endTime -set 4
foamDictionary 2/T.liquid -entry boundaryField/wall2/q -set 'uniform 1e5'
runApplication -a $(getApplication)
fi
#------------------------------------------------------------------------------
cd 切换当前工作目录。
restore0Dir 将 0.orig 恢复为求解所用的 0 目录。
blockMesh 读取 blockMeshDict，生成由六面体块组成的网格。
从 system/controlDict 的 application 读取求解器名称，运行后将日志保存在算例目录。
notTest 检查参数列表是否省略 -test。
cp 复制文件或目录。
foamDictionary 读取、修改和展开 OpenFOAM 字典。
