配置出处：OpenCFD OpenFOAM v2512 官方教程 incompressible/pimpleFoam/LES/periodicPlaneChannel/Allrun（原文件）。
#!/bin/sh
cd "${0%/*}" || exit # Run from this directory
. ${WM_PROJECT_DIR:?}/bin/tools/RunFunctions # Tutorial run functions
#------------------------------------------------------------------------------
# settings
# flag to enable computations in parallel mode
parallel=true
#------------------------------------------------------------------------------
restore0Dir
if [ ! -d constant/polyMesh ]
then
runApplication blockMesh
runApplication renumberMesh -overwrite -constant
runApplication checkMesh -allTopology -allGeometry -constant
fi
if [ "$parallel" = true ]
then
runApplication decomposePar -cellDist
runParallel $(getApplication)
runApplication reconstructPar
else
runApplication $(getApplication)
fi
runApplication postChannel
#------------------------------------------------------------------------------
cd 切换当前工作目录。
restore0Dir 将 0.orig 恢复为求解所用的 0 目录。
blockMesh 读取 blockMeshDict，生成由六面体块组成的网格。
renumberMesh 重排单元与面编号以减小矩阵带宽，并同步重排场。结果覆盖当前网格。
checkMesh 检查网格拓扑、几何形状与质量，并定位问题区域。
decomposePar 把网格和场划分到多个处理器子域。
从 system/controlDict 的 application 读取求解器名称，运行后将日志保存在算例目录。
reconstructPar 把并行结果的字段重构到完整案例。
postChannel 把通道湍流统计场沿均匀方向平均为壁法向剖面。
